        if (now - (lastWebChat.get(ip) || 0) < CHAT_COOLDOWN_MS) { res.writeHead(429, { "Content-Type": "application/json" }); res.end(JSON.stringify({ error: "Wait 15 seconds between messages" })); return; }
        let data = {}; try { data = JSON.parse(body || "{}"); } catch (_) {}
